module t9_keypress #(\n    parameter DICT_SIZE = 8,\n    parameter MAX_WORD_LEN = 8,\n    parameter MAX_QUERY_LEN = 16\n) (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [7:0] dict_words [0:DICT_SIZE-1][0:MAX_WORD_LEN-1],\n    input wire [3:0] dict_lengths [0:DICT_SIZE-1],\n    input wire [7:0] query_word [0:MAX_QUERY_LEN-1],\n    input wire [4:0] query_length,\n    output reg [7:0] key_sequence [0:255],\n    output reg [7:0] key_count,\n    output reg done\n);\n\n    // State machine states\n    localparam [1:0] IDLE = 2'd0;\n    localparam [1:0] COMPUTE_COSTS = 2'd1;\n    localparam [1:0] DP_COMPUTE = 2'd2;\n    localparam [1:0] BACKTRACK = 2'd3;\n    localparam [1:0] OUTPUT = 2'd4;\n    reg [1:0] state;\n\n    // T9 mapping lookup function\n    function automatic [3:0] char_to_digit(input [7:0] c);\n        case (c)\n            "a", "b", "c": char_to_digit = 4'd2;\n            "d", "e", "f": char_to_digit = 4'd3;\n            "g", "h", "i": char_to_digit = 4'd4;\n            "j", "k", "l": char_to_digit = 4'd5;\n            "m", "n", "o": char_to_digit = 4'd6;\n            "p", "q", "r", "s": char_to_digit = 4'd7;\n            "t", "u", "v": char_to_digit = 4'd8;\n            "w", "x", "y", "z": char_to_digit = 4'd9;\n            default: char_to_digit = 4'd0;\n        endcase\n    endfunction\n\n    // DP arrays\n    reg [31:0] dp [0:MAX_QUERY_LEN];\n    reg [31:0] dp_prev [0:MAX_QUERY_LEN];\n    reg [31:0] dp_word_idx [0:MAX_QUERY_LEN];\n    reg [31:0] dp_cycle_cost [0:MAX_QUERY_LEN];\n\n    // Word properties\n    reg [31:0] word_costs [0:DICT_SIZE-1];\n    reg [3:0] word_digit_seqs [0:DICT_SIZE-1][0:MAX_WORD_LEN-1];\n\n    // Counters and temporary registers\n    reg [4:0] i, j, k;\n    reg [31:0] min_cost, current_cost;\n    reg [31:0] backtrack_idx;\n    reg [7:0] output_idx;\n    reg [7:0] temp_key;\n\n    // Output buffer\n    reg [7:0] out_buf [0:255];\n    reg [7:0] out_len;\n\n    // Cycle counter to prevent infinite loops\n    reg [7:0] cycle_count;\n    localparam [7:0] MAX_CYCLES = 8'd200;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            key_count <= 8'd0;\n            out_len <= 8'd0;\n            cycle_count <= 8'd0;\n            for (i = 0; i < MAX_QUERY_LEN; i = i + 1) begin\n                dp[i] <= 32'd0;\n                dp_prev[i] <= 32'd0;\n                dp_word_idx[i] <= 32'd0;\n                dp_cycle_cost[i] <= 32'd0;\n            end\n            for (i = 0; i < DICT_SIZE; i = i + 1) begin\n                word_costs[i] <= 32'd0;\n                for (j = 0; j < MAX_WORD_LEN; j = j + 1) begin\n                    word_digit_seqs[i][j] <= 4'd0;\n                end\n            end\n            for (i = 0; i < 256; i = i + 1) begin\n                key_sequence[i] <= 8'd0;\n                out_buf[i] <= 8'd0;\n            end\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    cycle_count <= 8'd0;\n                    if (start) begin\n                        state <= COMPUTE_COSTS;\n                        i <= 5'd0;\n                        j <= 5'd0;\n                    end\n                end\n                \n                COMPUTE_COSTS: begin\n                    cycle_count <= cycle_count + 8'd1;\n                    if (j < dict_lengths[i]) begin\n                        word_digit_seqs[i][j] <= char_to_digit(dict_words[i][j]);\n                        j <= j + 1;\n                    end else begin\n                        word_costs[i] <= dict_lengths[i];\n                        i <= i + 1;\n                        j <= 5'd0;\n                        if (i == DICT_SIZE) begin\n                            state <= DP_COMPUTE;\n                            i <= 5'd0;\n                            j <= 5'd0;\n                            dp[0] <= 32'd0;\n                        end\n                    end\n                    if (cycle_count >= MAX_CYCLES) begin\n                        state <= IDLE;\n                    end\n                end\n                \n                DP_COMPUTE: begin\n                    cycle_count <= cycle_count + 8'd1;\n                    if (i <= query_length) begin\n                        if (j < DICT_SIZE) begin\n                            if (i + dict_lengths[j] <= query_length) begin\n                                current_cost = dp[i] + word_costs[j];\n                                if (i > 0) begin\n                                    current_cost = current_cost + 32'd1;\n                                end\n                                if (current_cost < dp[i + dict_lengths[j]] || dp[i + dict_lengths[j]] == 32'd0) begin\n                                    dp[i + dict_lengths[j]] <= current_cost;\n                                    dp_prev[i + dict_lengths[j]] <= i;\n                                    dp_word_idx[i + dict_lengths[j]] <= j;\n                                    dp_cycle_cost[i + dict_lengths[j]] <= 32'd0;\n                                end\n                            end\n                            j <= j + 1;\n                        end else begin\n                            j <= 5'd0;\n                            i <= i + 1;\n                        end\n                    end else begin\n                        state <= BACKTRACK;\n                        backtrack_idx <= query_length;\n                        out_len <= 8'd0;\n                    end\n                    if (cycle_count >= MAX_CYCLES) begin\n                        state <= IDLE;\n                    end\n                end\n                \n                BACKTRACK: begin\n                    cycle_count <= cycle_count + 8'd1;\n                    if (backtrack_idx > 0) begin\n                        if (out_len < 250) begin\n                            for (k = 0; k < dict_lengths[dp_word_idx[backtrack_idx]]; k = k + 1) begin\n                                out_buf[out_len] <= (word_digit_seqs[dp_word_idx[backtrack_idx]][k] + 8'h30);\n                                out_len <= out_len + 1;\n                            end\n                            if (dp_prev[backtrack_idx] > 0) begin\n                                out_buf[out_len] <= "R";\n                                out_len <= out_len + 1;\n                            end\n                            backtrack_idx <= dp_prev[backtrack_idx];\n                        end else begin\n                            state <= OUTPUT;\n                            output_idx <= 8'd0;\n                        end\n                    end else begin\n                        state <= OUTPUT;\n                        output_idx <= 8'd0;\n                    end\n                    if (cycle_count >= MAX_CYCLES) begin\n                        state <= IDLE;\n                    end\n                end\n                \n                OUTPUT: begin\n                    cycle_count <= cycle_count + 8'd1;\n                    if (output_idx < out_len) begin\n                        key_sequence[output_idx] <= out_buf[output_idx];\n                        output_idx <= output_idx + 1;\n                        key_count <= out_len;\n                    end else begin\n                        done <= 1'b1;\n                        state <= IDLE;\n                    end\n                    if (cycle_count >= MAX_CYCLES) begin\n                        state <= IDLE;\n                    end\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule